// Run after Hugo: node scripts/check-social-images.mjs public
import assert from 'node:assert/strict';
import {readFileSync, readdirSync} from 'node:fs';
import {resolve, join, relative, sep} from 'node:path';

const root = resolve(process.argv[2] || 'public');
const origin = process.argv[3] || 'https://jdx.dev/';
const attributes = (tag) => Object.fromEntries(
  [...tag.matchAll(/([\w:-]+)=(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g)]
    .map(([, name, quoted, single, bare]) => [name, quoted ?? single ?? bare]));
const tags = (html, name) => [...html.matchAll(new RegExp(`<${name}\\b[^>]*>`, 'g'))]
  .map(([tag]) => attributes(tag));
const meta = (html, key) => {
  const matches = tags(html, 'meta').filter((tag) => tag.property === key || tag.name === key);
  assert.equal(matches.length, 1, `Expected one ${key} tag`);
  return matches[0].content;
};
const walk = (dir) => readdirSync(dir, {withFileTypes: true}).flatMap((entry) =>
  entry.isDirectory() ? walk(join(dir, entry.name)) : [join(dir, entry.name)]);
let posts = 0;
const images = new Set();
for (const file of walk(join(root, 'posts')).filter((file) => file.endsWith('.html'))) {
  const html = readFileSync(file, 'utf8');
  if (!html.includes('og:type') || meta(html, 'og:type') !== 'article') continue;
  const links = tags(html, 'link');
  const canonical = links.filter((link) => link.rel === 'canonical');
  assert.equal(canonical.length, 1, 'Expected one canonical link');
  const pagePath = relative(root, file).split(sep).join('/').replace(/index\.html$/, '');
  assert.equal(canonical[0].href, new URL(pagePath, origin).href, 'Canonical must match the published page URL');
  assert.equal(meta(html, 'og:url'), canonical[0].href);
  assert.ok(links.some((link) => link.rel === 'icon' && link.type === 'image/png' && link.href === '/favicon-32x32.png'));
  const image = meta(html, 'og:image');
  assert.equal(meta(html, 'twitter:image'), image);
  assert.equal(meta(html, 'twitter:image:alt'), meta(html, 'og:image:alt'));
  assert.match(image, /^https:\/\//);
  assert.notEqual(new URL(image).pathname, '/og.png');
  const png = readFileSync(join(root, new URL(image).pathname));
  assert.deepEqual([...png.subarray(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10]);
  assert.equal(png.readUInt32BE(16), 1200);
  assert.equal(png.readUInt32BE(20), 630);
  images.add(image);
  posts++;
}
assert.ok(posts > 0, 'No built posts found');
const favicon = readFileSync(join(root, 'favicon-32x32.png'));
assert.deepEqual([...favicon.subarray(0, 8)], [137, 80, 78, 71, 13, 10, 26, 10]);
assert.equal(images.size, posts, 'Each post should have its own image');
assert.equal(new URL(meta(readFileSync(join(root, 'index.html'), 'utf8'), 'og:image')).pathname, '/og.png');
console.log(`Checked images, canonicals, and PNG favicon for ${posts} posts; homepage fallback preserved.`);
scripts/update-github-stars.mjs
import {readFile, writeFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';

const owner = 'jdx';
const dataPath = new URL('../data/oss.toml', import.meta.url);
const homebrewAnalyticsUrl = 'https://formulae.brew.sh/api/analytics/install-on-request/30d.json';

export function formatStars(count) {
	if (count < 1000) return String(count);
	return `${(count / 1000).toFixed(1).replace(/\.0$/, '')}k`;
}

function replaceTomlString(block, key, value) {
	const pattern = new RegExp(`^${key} = ".*"$`, 'm');
	if (!pattern.test(block)) {
		throw new Error(`Missing ${key} in TOML block`);
	}
	return block.replace(pattern, `${key} = "${value}"`);
}

function fullRepositoryName(name) {
	return name.includes('/') ? name : `${owner}/${name}`;
}

export function updateStarData(source, repositories) {
	const starsByRepository = new Map(
		repositories.map(repository => [repository.full_name, repository.stargazers_count]),
	);
	const miseStars = starsByRepository.get(`${owner}/mise`);
	if (miseStars === undefined) {
		throw new Error('GitHub response did not include jdx/mise');
	}

	const totalStars = repositories
		.filter(repository => !repository.archived && !repository.fork)
		.reduce((total, repository) => total + repository.stargazers_count, 0);

	let updated = source.replace(
		/\[\[stats\]\][\s\S]*?(?=\n\[\[|$)/g,
		block => {
			if (block.includes('label = "stars on mise"')) {
				return replaceTomlString(block, 'value', `${formatStars(miseStars)}+`);
			}
			if (block.includes('label = "stars across repos"')) {
				return replaceTomlString(block, 'value', `${formatStars(totalStars)}+`);
			}
			return block;
		},
	);

	updated = updated.replace(
		/\[\[projects\]\][\s\S]*?(?=\n\[\[|$)/g,
		block => {
			const repositoryName = block.match(/^repo = "([^"]+)"$/m)?.[1];
			if (!repositoryName) return block;
			const stars = starsByRepository.get(fullRepositoryName(repositoryName));
			if (stars === undefined) {
				throw new Error(`GitHub response did not include ${fullRepositoryName(repositoryName)}`);
			}
			return replaceTomlString(block, 'stars', formatStars(stars));
		},
	);

	const projectPattern = /\[\[projects\]\][\s\S]*?(?=\n\[\[|$)/g;
	const projects = [...updated.matchAll(projectPattern)];
	if (projects.length > 1) {
		const sortedProjects = projects
			.map(match => match[0])
			.sort((a, b) => {
				const aRepository = a.match(/^repo = "([^"]+)"$/m)?.[1] ?? '';
				const bRepository = b.match(/^repo = "([^"]+)"$/m)?.[1] ?? '';
				const aStars = starsByRepository.get(fullRepositoryName(aRepository)) ?? -1;
				const bStars = starsByRepository.get(fullRepositoryName(bRepository)) ?? -1;
				const starDifference = bStars - aStars;
				return starDifference || aRepository.localeCompare(bRepository);
			});
		const firstProject = projects[0];
		const lastProject = projects.at(-1);
		const projectsEnd = lastProject.index + lastProject[0].length;
		updated = `${updated.slice(0, firstProject.index)}${sortedProjects.join('\n')}${updated.slice(projectsEnd)}`;
	}

	return updated;
}

export function updateHomebrewRank(source, items) {
	const mise = items.find(item => item.formula === 'mise');
	if (!Number.isInteger(mise?.number) || mise.number < 1) {
		throw new Error('Homebrew analytics did not include a valid mise ranking');
	}

	return source.replace(
		/\[\[stats\]\][\s\S]*?(?=\n\[\[|$)/g,
		block => block.includes('label = "most-installed Homebrew formula"')
			? replaceTomlString(block, 'value', `#${mise.number}`)
			: block,
	);
}

export async function fetchRepositories(token, source, fetchImpl = fetch) {
	const repositories = [];
	const headers = {
		Accept: 'application/vnd.github+json',
		Authorization: `Bearer ${token}`,
		'User-Agent': 'jdx.dev-star-updater',
		'X-GitHub-Api-Version': '2022-11-28',
	};
	let url = `https://api.github.com/users/${owner}/repos?per_page=100&type=owner`;
	while (url) {
		const response = await fetchImpl(url, {headers});
		if (!response.ok) {
			throw new Error(`GitHub API returned ${response.status}: ${await response.text()}`);
		}
		repositories.push(...await response.json());
		url = response.headers.get('link')
			?.split(',')
			.map(part => part.trim().match(/^<([^>]+)>; rel="([^"]+)"$/))
			.find(match => match?.[2] === 'next')?.[1];
	}
	const knownRepositories = new Set(repositories.map(repository => repository.full_name));
	const projectRepositories = new Set(
		[...source.matchAll(/^repo = "([^"]+)"$/gm)]
			.map(match => fullRepositoryName(match[1])),
	);
	for (const name of projectRepositories) {
		if (knownRepositories.has(name)) continue;
		const response = await fetchImpl(`https://api.github.com/repos/${name}`, {headers});
		if (!response.ok) {
			throw new Error(`GitHub API returned ${response.status} for ${name}: ${await response.text()}`);
		}
		const repository = await response.json();
		if (!knownRepositories.has(repository.full_name)) {
			repositories.push(repository);
			knownRepositories.add(repository.full_name);
		}
	}
	return repositories;
}

async function fetchHomebrewAnalytics() {
	const response = await fetch(homebrewAnalyticsUrl, {
		headers: {
			Accept: 'application/json',
			'User-Agent': 'jdx.dev-stats-updater',
		},
	});
	if (!response.ok) {
		throw new Error(`Homebrew analytics API returned ${response.status}: ${await response.text()}`);
	}
	const analytics = await response.json();
	if (!Array.isArray(analytics.items)) {
		throw new Error('Homebrew analytics response did not include items');
	}
	return analytics.items;
}

async function main() {
	const token = process.env.GITHUB_TOKEN;
	if (!token) throw new Error('GITHUB_TOKEN is required');
	const source = await readFile(dataPath, 'utf8');
	const [repositories, homebrewItems] = await Promise.all([
		fetchRepositories(token, source),
		fetchHomebrewAnalytics(),
	]);
	const updated = updateHomebrewRank(updateStarData(source, repositories), homebrewItems);
	if (updated !== source) await writeFile(dataPath, updated);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
	await main();
}
scripts/update-github-stars.test.mjs
import assert from 'node:assert/strict';
import test from 'node:test';
import {fetchRepositories, formatStars, updateHomebrewRank, updateStarData} from './update-github-stars.mjs';

test('formats exact and compact star counts', () => {
	assert.equal(formatStars(999), '999');
	assert.equal(formatStars(1000), '1k');
	assert.equal(formatStars(1790), '1.8k');
	assert.equal(formatStars(31_402), '31.4k');
});

test('updates homepage star counts from repository data', () => {
	const source = `[[stats]]
value = "30.4k+"
label = "stars on mise"

[[stats]]
value = "38.9k+"
label = "stars across repos"

[[projects]]
name = "mise"
repo = "mise"
stars = "30.4k"

[[projects]]
name = "Example"
repo = "example"
stars = "9"
`;
	const repositories = [
		{full_name: 'jdx/mise', stargazers_count: 31_402, archived: false, fork: false},
		{full_name: 'jdx/example', stargazers_count: 1200, archived: false, fork: false},
		{full_name: 'jdx/archived', stargazers_count: 500, archived: true, fork: false},
		{full_name: 'jdx/fork', stargazers_count: 1000, archived: false, fork: true},
	];
	const updated = updateStarData(source, repositories);

	assert.match(updated, /value = "31\.4k\+"\nlabel = "stars on mise"/);
	assert.match(updated, /value = "32\.6k\+"\nlabel = "stars across repos"/);
	assert.match(updated, /repo = "mise"\nstars = "31\.4k"/);
	assert.match(updated, /repo = "example"\nstars = "1\.2k"/);
});

test('sorts homepage projects by descending star count', () => {
	const source = `[[stats]]
value = "30.4k+"
label = "stars on mise"

[[stats]]
value = "38.9k+"
label = "stars across repos"

[[projects]]
name = "mise"
repo = "mise"
stars = "30.4k"

[[projects]]
name = "Example"
repo = "example"
stars = "2k"

[[projects]]
name = "Popular"
repo = "popular"
stars = "10k"
`;
	const repositories = [
		{full_name: 'jdx/mise', stargazers_count: 31_402, archived: false, fork: false},
		{full_name: 'jdx/example', stargazers_count: 2200, archived: false, fork: false},
		{full_name: 'jdx/popular', stargazers_count: 12_000, archived: false, fork: false},
	];
	const updated = updateStarData(source, repositories);
	const projectOrder = [...updated.matchAll(/^repo = "([^"]+)"$/gm)]
		.map(match => match[1]);

	assert.deepEqual(projectOrder, ['mise', 'popular', 'example']);
});

test('updates the homepage Homebrew ranking from analytics data', () => {
	const source = `[[stats]]
value = "#20"
label = "most-installed Homebrew formula"
href = "https://formulae.brew.sh/analytics/install-on-request/30d/"
`;
	const items = [
		{number: 14, formula: 'jq'},
		{number: 15, formula: 'mise'},
	];

	assert.match(updateHomebrewRank(source, items), /value = "#15"/);
});

test('rejects Homebrew analytics without a valid mise ranking', () => {
	assert.throws(
		() => updateHomebrewRank('', [{number: 15, formula: 'jq'}]),
		/Homebrew analytics did not include a valid mise ranking/,
	);
});

test('fetches organization projects after all owner pages without double-counting', async () => {
	const mise = {full_name: 'jdx/mise', stargazers_count: 1000};
	const personalAube = {full_name: 'jdx/aube', stargazers_count: 10};
	const aube = {full_name: 'aubepkg/aube', stargazers_count: 1965};
	const source = `[[stats]]
value = "0"
label = "stars across repos"

[[projects]]
repo = "mise"
stars = "0"

[[projects]]
repo = "aubepkg/aube"
stars = "0"

[[projects]]
repo = "aube"
stars = "0"

[[projects]]
repo = "jdx/mise"
stars = "0"
`;
	const calls = [];
	const repositories = await fetchRepositories('test-token', source, async url => {
		calls.push(url);
		if (calls.length === 1) {
			return Response.json([mise], {
				headers: {link: '<https://api.github.com/users/jdx/repos?page=2>; rel="next"'},
			});
		}
		if (calls.length === 2) return Response.json([personalAube]);
		return Response.json(aube);
	});
	assert.deepEqual(calls, [
		'https://api.github.com/users/jdx/repos?per_page=100&type=owner',
		'https://api.github.com/users/jdx/repos?page=2',
		'https://api.github.com/repos/aubepkg/aube',
	]);
	assert.deepEqual(repositories, [mise, personalAube, aube]);
	const updated = updateStarData(source, repositories);
	assert.match(updated, /value = "3k\+"/);
	assert.match(updated, /repo = "aubepkg\/aube"\nstars = "2k"/);
	assert.match(updated, /repo = "aube"\nstars = "10"/);
	assert.deepEqual([...updated.matchAll(/^repo = "([^"]+)"$/gm)].map(match => match[1]),
		['aubepkg/aube', 'jdx/mise', 'mise', 'aube']);
});

test('fails clearly when a configured organization repository cannot be fetched', async () => {
	await assert.rejects(
		fetchRepositories('test-token', 'repo = "aubepkg/aube"', async url =>
			url.includes('/users/') ? Response.json([]) : new Response('Not Found', {status: 404})),
		/GitHub API returned 404 for aubepkg\/aube/,
	);
});

