import {readFile, writeFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';

const owner = 'jdx';
const dataPath = new URL('../data/oss.toml', import.meta.url);
const homebrewAnalyticsUrl = 'https://formulae.brew.sh/api/analytics/install-on-request/30d.json';

export function formatStars(count) {
	if (count < 1000) return String(count);
	return `${(count / 1000).toFixed(1).replace(/\.0$/, '')}k`;
}

function replaceTomlString(block, key, value) {
	const pattern = new RegExp(`^${key} = ".*"$`, 'm');
	if (!pattern.test(block)) {
		throw new Error(`Missing ${key} in TOML block`);
	}
	return block.replace(pattern, `${key} = "${value}"`);
}

function fullRepositoryName(name) {
	return name.includes('/') ? name : `${owner}/${name}`;
}

export function updateStarData(source, repositories) {
	const starsByRepository = new Map(
		repositories.map(repository => [repository.full_name, repository.stargazers_count]),
	);
	const miseStars = starsByRepository.get(`${owner}/mise`);
	if (miseStars === undefined) {
		throw new Error('GitHub response did not include jdx/mise');
	}

	const totalStars = repositories
		.filter(repository => !repository.archived && !repository.fork)
		.reduce((total, repository) => total + repository.stargazers_count, 0);

	let updated = source.replace(
		/\[\[stats\]\][\s\S]*?(?=\n\[\[|$)/g,
		block => {
			if (block.includes('label = "stars on mise"')) {
				return replaceTomlString(block, 'value', `${formatStars(miseStars)}+`);
			}
			if (block.includes('label = "stars across repos"')) {
				return replaceTomlString(block, 'value', `${formatStars(totalStars)}+`);
			}
			return block;
		},
	);

	updated = updated.replace(
		/\[\[projects\]\][\s\S]*?(?=\n\[\[|$)/g,
		block => {
			const repositoryName = block.match(/^repo = "([^"]+)"$/m)?.[1];
			if (!repositoryName) return block;
			const stars = starsByRepository.get(fullRepositoryName(repositoryName));
			if (stars === undefined) {
				throw new Error(`GitHub response did not include ${fullRepositoryName(repositoryName)}`);
			}
			return replaceTomlString(block, 'stars', formatStars(stars));
		},
	);

	const projectPattern = /\[\[projects\]\][\s\S]*?(?=\n\[\[|$)/g;
	const projects = [...updated.matchAll(projectPattern)];
	if (projects.length > 1) {
		const sortedProjects = projects
			.map(match => match[0])
			.sort((a, b) => {
				const aRepository = a.match(/^repo = "([^"]+)"$/m)?.[1] ?? '';
				const bRepository = b.match(/^repo = "([^"]+)"$/m)?.[1] ?? '';
				const aStars = starsByRepository.get(fullRepositoryName(aRepository)) ?? -1;
				const bStars = starsByRepository.get(fullRepositoryName(bRepository)) ?? -1;
				const starDifference = bStars - aStars;
				return starDifference || aRepository.localeCompare(bRepository);
			});
		const firstProject = projects[0];
		const lastProject = projects.at(-1);
		const projectsEnd = lastProject.index + lastProject[0].length;
		updated = `${updated.slice(0, firstProject.index)}${sortedProjects.join('\n')}${updated.slice(projectsEnd)}`;
	}

	return updated;
}

export function updateHomebrewRank(source, items) {
	const mise = items.find(item => item.formula === 'mise');
	if (!Number.isInteger(mise?.number) || mise.number < 1) {
		throw new Error('Homebrew analytics did not include a valid mise ranking');
	}

	return source.replace(
		/\[\[stats\]\][\s\S]*?(?=\n\[\[|$)/g,
		block => block.includes('label = "most-installed Homebrew formula"')
			? replaceTomlString(block, 'value', `#${mise.number}`)
			: block,
	);
}

export async function fetchRepositories(token, source, fetchImpl = fetch) {
	const repositories = [];
	const headers = {
		Accept: 'application/vnd.github+json',
		Authorization: `Bearer ${token}`,
		'User-Agent': 'jdx.dev-star-updater',
		'X-GitHub-Api-Version': '2022-11-28',
	};
	let url = `https://api.github.com/users/${owner}/repos?per_page=100&type=owner`;
	while (url) {
		const response = await fetchImpl(url, {headers});
		if (!response.ok) {
			throw new Error(`GitHub API returned ${response.status}: ${await response.text()}`);
		}
		repositories.push(...await response.json());
		url = response.headers.get('link')
			?.split(',')
			.map(part => part.trim().match(/^<([^>]+)>; rel="([^"]+)"$/))
			.find(match => match?.[2] === 'next')?.[1];
	}
	const knownRepositories = new Set(repositories.map(repository => repository.full_name));
	const projectRepositories = new Set(
		[...source.matchAll(/^repo = "([^"]+)"$/gm)]
			.map(match => fullRepositoryName(match[1])),
	);
	for (const name of projectRepositories) {
		if (knownRepositories.has(name)) continue;
		const response = await fetchImpl(`https://api.github.com/repos/${name}`, {headers});
		if (!response.ok) {
			throw new Error(`GitHub API returned ${response.status} for ${name}: ${await response.text()}`);
		}
		const repository = await response.json();
		if (!knownRepositories.has(repository.full_name)) {
			repositories.push(repository);
			knownRepositories.add(repository.full_name);
		}
	}
	return repositories;
}

async function fetchHomebrewAnalytics() {
	const response = await fetch(homebrewAnalyticsUrl, {
		headers: {
			Accept: 'application/json',
			'User-Agent': 'jdx.dev-stats-updater',
		},
	});
	if (!response.ok) {
		throw new Error(`Homebrew analytics API returned ${response.status}: ${await response.text()}`);
	}
	const analytics = await response.json();
	if (!Array.isArray(analytics.items)) {
		throw new Error('Homebrew analytics response did not include items');
	}
	return analytics.items;
}

async function main() {
	const token = process.env.GITHUB_TOKEN;
	if (!token) throw new Error('GITHUB_TOKEN is required');
	const source = await readFile(dataPath, 'utf8');
	const [repositories, homebrewItems] = await Promise.all([
		fetchRepositories(token, source),
		fetchHomebrewAnalytics(),
	]);
	const updated = updateHomebrewRank(updateStarData(source, repositories), homebrewItems);
	if (updated !== source) await writeFile(dataPath, updated);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
	await main();
}
