import assert from 'node:assert/strict';
import test from 'node:test';
import {fetchRepositories, formatStars, updateHomebrewRank, updateStarData} from './update-github-stars.mjs';

test('formats exact and compact star counts', () => {
	assert.equal(formatStars(999), '999');
	assert.equal(formatStars(1000), '1k');
	assert.equal(formatStars(1790), '1.8k');
	assert.equal(formatStars(31_402), '31.4k');
});

test('updates homepage star counts from repository data', () => {
	const source = `[[stats]]
value = "30.4k+"
label = "stars on mise"

[[stats]]
value = "38.9k+"
label = "stars across repos"

[[projects]]
name = "mise"
repo = "mise"
stars = "30.4k"

[[projects]]
name = "Example"
repo = "example"
stars = "9"
`;
	const repositories = [
		{full_name: 'jdx/mise', stargazers_count: 31_402, archived: false, fork: false},
		{full_name: 'jdx/example', stargazers_count: 1200, archived: false, fork: false},
		{full_name: 'jdx/archived', stargazers_count: 500, archived: true, fork: false},
		{full_name: 'jdx/fork', stargazers_count: 1000, archived: false, fork: true},
	];
	const updated = updateStarData(source, repositories);

	assert.match(updated, /value = "31\.4k\+"\nlabel = "stars on mise"/);
	assert.match(updated, /value = "32\.6k\+"\nlabel = "stars across repos"/);
	assert.match(updated, /repo = "mise"\nstars = "31\.4k"/);
	assert.match(updated, /repo = "example"\nstars = "1\.2k"/);
});

test('sorts homepage projects by descending star count', () => {
	const source = `[[stats]]
value = "30.4k+"
label = "stars on mise"

[[stats]]
value = "38.9k+"
label = "stars across repos"

[[projects]]
name = "mise"
repo = "mise"
stars = "30.4k"

[[projects]]
name = "Example"
repo = "example"
stars = "2k"

[[projects]]
name = "Popular"
repo = "popular"
stars = "10k"
`;
	const repositories = [
		{full_name: 'jdx/mise', stargazers_count: 31_402, archived: false, fork: false},
		{full_name: 'jdx/example', stargazers_count: 2200, archived: false, fork: false},
		{full_name: 'jdx/popular', stargazers_count: 12_000, archived: false, fork: false},
	];
	const updated = updateStarData(source, repositories);
	const projectOrder = [...updated.matchAll(/^repo = "([^"]+)"$/gm)]
		.map(match => match[1]);

	assert.deepEqual(projectOrder, ['mise', 'popular', 'example']);
});

test('updates the homepage Homebrew ranking from analytics data', () => {
	const source = `[[stats]]
value = "#20"
label = "most-installed Homebrew formula"
href = "https://formulae.brew.sh/analytics/install-on-request/30d/"
`;
	const items = [
		{number: 14, formula: 'jq'},
		{number: 15, formula: 'mise'},
	];

	assert.match(updateHomebrewRank(source, items), /value = "#15"/);
});

test('rejects Homebrew analytics without a valid mise ranking', () => {
	assert.throws(
		() => updateHomebrewRank('', [{number: 15, formula: 'jq'}]),
		/Homebrew analytics did not include a valid mise ranking/,
	);
});

test('fetches organization projects after all owner pages without double-counting', async () => {
	const mise = {full_name: 'jdx/mise', stargazers_count: 1000};
	const personalAube = {full_name: 'jdx/aube', stargazers_count: 10};
	const aube = {full_name: 'aubepkg/aube', stargazers_count: 1965};
	const source = `[[stats]]
value = "0"
label = "stars across repos"

[[projects]]
repo = "mise"
stars = "0"

[[projects]]
repo = "aubepkg/aube"
stars = "0"

[[projects]]
repo = "aube"
stars = "0"

[[projects]]
repo = "jdx/mise"
stars = "0"
`;
	const calls = [];
	const repositories = await fetchRepositories('test-token', source, async url => {
		calls.push(url);
		if (calls.length === 1) {
			return Response.json([mise], {
				headers: {link: '<https://api.github.com/users/jdx/repos?page=2>; rel="next"'},
			});
		}
		if (calls.length === 2) return Response.json([personalAube]);
		return Response.json(aube);
	});
	assert.deepEqual(calls, [
		'https://api.github.com/users/jdx/repos?per_page=100&type=owner',
		'https://api.github.com/users/jdx/repos?page=2',
		'https://api.github.com/repos/aubepkg/aube',
	]);
	assert.deepEqual(repositories, [mise, personalAube, aube]);
	const updated = updateStarData(source, repositories);
	assert.match(updated, /value = "3k\+"/);
	assert.match(updated, /repo = "aubepkg\/aube"\nstars = "2k"/);
	assert.match(updated, /repo = "aube"\nstars = "10"/);
	assert.deepEqual([...updated.matchAll(/^repo = "([^"]+)"$/gm)].map(match => match[1]),
		['aubepkg/aube', 'jdx/mise', 'mise', 'aube']);
});

