:focus-visible { outline: 2px solid var(--color-amber); outline-offset: 5px; }
#main:focus { outline: none; }
.skip-link { position: fixed; top: -6rem; left: 1rem; z-index: 10; padding: .75rem 1rem; background: var(--color-amber); color: var(--color-bg); }
.skip-link:focus { top: 1rem; }
.site-shell { padding-inline: clamp(1.25rem, 4vw, 2rem); }
.site-nav { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding-block: 1.75rem; border-bottom: 1px solid var(--color-border); margin-bottom: 3.5rem; }
.site-brand { font-weight: 700; font-size: 1.1rem; white-space: nowrap; }
.nav-items { display: flex; flex-wrap: wrap; gap: 1.25rem; align-items: center; }
.nav-link { color: var(--color-text); }
.footer-rss { float: right; color: var(--color-amber); margin-left: 1rem; }
h1, h2, h3 { text-wrap: balance; }
h1 { font-weight: 700 !important; letter-spacing: -.055em; overflow-wrap: anywhere; }
h2, h3 { font-weight: 700; letter-spacing: -.035em; }
.rounded-lg { border-radius: 3px; }
.home-intro { padding-block: .5rem 1.5rem; }
.home-intro img { width: 4rem; height: 4rem; filter: grayscale(100%); }
.home-intro h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); }
.eyebrow, .section-heading { color: var(--color-amber); font-size: .8rem; }
.eyebrow { display: block; margin-bottom: 1.25rem; }
.section-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; border-bottom: 1px solid var(--color-amber); padding-bottom: .9rem; }
.section-heading h2 { font-size: .85rem; letter-spacing: .05em; text-transform: uppercase; }
.section-heading a:hover { text-decoration: underline; }
.writing-section { margin-bottom: 5rem; }
.post-row { border-bottom: 1px solid var(--color-border); padding: 1.65rem 0; }
{{- /* Generate post cards with bundled fonts; no network or extra build tool. */ -}}
{{- $image := "og.png" | absURL -}}
{{- $alt := "Jeff Dickey (@jdx) — open source developer tools" -}}
{{- if and .IsPage (eq .Section "posts") -}}
  {{- $title := .Title | plainify | htmlUnescape -}}
  {{- $alt = printf "%s — jdx.dev" $title -}}
  {{- $font := resources.FromString "social/Merriweather-Regular.ttf" (readFile "static/fonts/Merriweather/Merriweather-Regular.ttf") -}}
  {{- $labelFont := resources.FromString "social/Oswald-Regular.ttf" (readFile "static/fonts/Oswald/static/Oswald-Regular.ttf") -}}
  {{- $size := 60 -}}
  {{- if gt (len $title) 60 -}}{{- $size = 48 -}}{{- end -}}
  {{- if gt (len $title) 100 -}}{{- $size = 32 -}}{{- end -}}
  {{- if gt (len $title) 180 -}}{{- $size = 24 -}}{{- end -}}
  {{- /* Bound unusually long titles so the date always remains readable. */ -}}
  {{- $displayTitle := $title | truncate 260 -}}
  {{- $card := resources.Get "social/background.png" -}}
  {{- $card = $card.Filter
    (images.Text "jdx.dev / blog" (dict "font" $labelFont "size" 30 "color" "#d69b42" "x" 72 "y" 58))
    (images.Text $displayTitle (dict "font" $font "size" $size "color" "#f1eee7" "x" 72 "y" 154 "linespacing" 14))
    (images.Text (printf "%s  ·  Jeff Dickey" (.Date.Format "January 2, 2006")) (dict "font" $labelFont "size" 27 "color" "#b7afa2" "x" 72 "y" 552))
  -}}
  {{- $image = $card.Permalink -}}
{{- end -}}
{{- return (dict "url" $image "alt" $alt) -}}

