import assert from 'node:assert/strict';
import {readFileSync, readdirSync} from 'node:fs';
import {join} from 'node:path';
import test from 'node:test';

const postsDir = new URL('../content/posts/', import.meta.url);

test('every post has a concise social description', () => {
	for (const filename of readdirSync(postsDir).filter(name => name.endsWith('.md'))) {
		const source = readFileSync(join(postsDir.pathname, filename), 'utf8');
		const frontmatter = source.match(/^---\r?\n([\s\S]*?)\r?\n---/)?.[1];
		assert.ok(frontmatter, `${filename} must have YAML frontmatter`);
		const value = frontmatter.match(/^description:\s*(.+)$/m)?.[1].trim();
		assert.ok(value, `${filename} must have a description`);
		const description = value.replace(/^(?:"([\s\S]*)"|'([\s\S]*)')$/, '$1$2').trim();
		assert.ok(description, `${filename} must have a non-empty description`);
		assert.ok(description.length <= 180, `${filename} description must be at most 180 characters`);
	}
});

